fix:
Use `OnceCell` (single-threaded) or `OnceLock` (thread-safe) so the accessor takes `&self`.
```rust
use std::cell::OnceCell;

pub struct ServiceRegistry { instance: OnceCell<String> }

impl ServiceRegistry {
    pub fn instance(&self) -> &str {
        self.instance.get_or_init(|| "Initialized".to_string())
    }
}
```
